import pathlib, sys
banned = ['session.v4', '.jsonl.zstd', 'dsh-session-format']
bad = []
for p in sorted(pathlib.Path('.').rglob('*.go')):
    if '.git' in p.parts:
        continue
    text = p.read_text(encoding='utf-8')
    for needle in banned:
        if needle in text:
            bad.append(p.as_posix() + ' mentions ' + needle)
print('Go format keeps its own identity: OK' if not bad else repr(bad))
sys.exit(1 if bad else 0)

