import pathlib, sys
mk = pathlib.Path('Makefile').read_text(encoding='utf-8')
main = pathlib.Path('scripts/doccheck/main.go').read_text(encoding='utf-8')
problems = []
for token in ['fmt-check', 'vet', 'test', 'coverage', 'docs', 'doc-examples', 'build']:
    if token not in mk:
        problems.append('Makefile lost gate ' + token)
for token in ['100 < current.total*90', 'has no coverage data']:
    if token not in main:
        problems.append('coverage gate weakened: ' + token)
print('gate integrity: OK' if not problems else 'problems: ' + repr(problems))
sys.exit(1 if problems else 0)

import pathlib, sys
text = pathlib.Path('docs/learning/index.md').read_text(encoding='utf-8')
problems = []
for link in ['../persistence/go-primer.md', '../persistence/format.md',
             '../persistence/recovery.md', '../persistence/cache.md']:
    if link not in text:
        problems.append('missing link ' + link)
if 'C10' not in text:
    problems.append('C10 is not listed as a current topic')
for stale in ['| C10 持久化与恢复 | C07、C09', 'C10 起属后续阶段']:
    if stale in text:
        problems.append('stale future row ' + stale)
print('learning index: OK' if not problems else 'problems: ' + repr(problems))
sys.exit(1 if problems else 0)

